import { useEffect, useRef } from 'react';
import { router, useRootNavigationState } from 'expo-router';
import { ActivityIndicator, View } from 'react-native';
import { useSession } from '../lib/session';
import { SIGNED_IN_HOME, clearReturnPath, noteExplicitLanding, readReturnPath } from '../lib/auth';
import { colors } from '../lib/theme';

export default function Index() {
  const { userId, loading } = useSession();
  const nav = useRootNavigationState();
  const sent = useRef(false);
  useEffect(() => {
    // Android drops a replace issued before the root navigator exists. <Redirect>
    // also waits on focus, which the first screen often never reports.
    if (loading || !nav?.key || sent.current) return;
    let cancelled = false;
    (async () => {
      if (!userId) {
        if (cancelled || sent.current) return;
        sent.current = true;
        router.replace('/sign-in');
        return;
      }
      const next = await readReturnPath();
      if (cancelled || sent.current) return;
      sent.current = true;
      clearReturnPath();
      if (next) noteExplicitLanding(next);
      router.replace(next ?? SIGNED_IN_HOME);
    })();
    return () => { cancelled = true; };
  }, [loading, userId, nav?.key]);
  return <View style={{ flex: 1, justifyContent: 'center' }}><ActivityIndicator color={colors.navy} /></View>;
}
